import { type Config, configure } from './config.js';
import * as events from './events.js';
import { render, renderResized, updateBounds } from './render.js';
import { defaults, type HeadlessState, type State } from './state.js';
import type * as cg from './types.js';
import * as svg from './svg.js';
import * as util from './util.js';
import { renderWrap } from './wrap.js';

export function initModule({ el, config }: { el: HTMLElement; config?: Config }): Api {
  return Chessground(el, config);
}

export function Chessground(element: HTMLElement, config?: Config): Api {
  const maybeState: State | HeadlessState = defaults();

  configure(maybeState, config || {});

  let boardUnbind: cg.Unbind | undefined;

  function redrawAll(): State {
    const prevUnbind = 'dom' in maybeState ? maybeState.dom.unbind : undefined;
    // the wrap element is being replaced, so disconnect the previous board bindings
    boardUnbind?.();
    // compute bounds from existing board element if possible
    // this allows non-square boards from CSS to be handled (for 3D)
    const elements = renderWrap(element, maybeState),
      bounds = util.memo(() => elements.board.getBoundingClientRect()),
      redrawNow = (skipSvg?: boolean): void => {
        render(state);
        if (elements.autoPieces) autoPieces.render(state, elements.autoPieces);
        if (!skipSvg && elements.shapes) svg.renderSvg(state, elements);
      },
      onResize = (): void => {
        updateBounds(state);
        renderResized(state);
        if (elements.autoPieces) autoPieces.renderResized(state);
      };
    const state = maybeState as State;
    state.dom = {
      elements,
      bounds,
      redraw: debounceRedraw(redrawNow),
      redrawNow,
      unbind: prevUnbind,
    };
    state.drawable.prevSvgHash = '';
    updateBounds(state);
    redrawNow(false);
    boardUnbind = events.bindBoard(state, onResize);
    if (!prevUnbind) {
      const documentUnbind = events.bindDocument(state, onResize);
      state.dom.unbind = () => {
        documentUnbind();
        boardUnbind?.();
      };
    }
    state.events.insert?.(elements);
    return state;
  }

  return start(redrawAll(), redrawAll);
}

function debounceRedraw(redrawNow: (skipSvg?: boolean) => void): () => void {
  let redrawing = false;
  return () => {
    if (redrawing) return;
    redrawing = true;
    requestAnimationFrame(() => {
      redrawNow();
      redrawing = false;
    });
  };
}

