  await page.addInitScript(() => {
    const RealRO = window.ResizeObserver;
    window.__ro = { live: 0, fires: 0 };
    window.ResizeObserver = class {
      constructor(cb) {
        this.__real = new RealRO(entries => {
          window.__ro.fires++;
          cb(entries);
        });
        window.__ro.live++;
      }
      observe(el) {
        this.__real.observe(el);
      }
      unobserve(el) {
